-- ISTDocAi development database: model upgrade of 2026-11-18.
--   AUTO     : IST-Classifier-v6 -> IST-Classifier-v7  (held-out 16/17; v6 11/17)
--   MANIFEST : manifest-v3       -> manifest-v4        (held-out 87.7%; v3 86.3%; NADIA label fixes)
--   BL       : bl-v3 unchanged.
-- Run in SSMS against your migrated ISTDocAi development database (the one DevSetup seeded). No SQLCMD mode.
-- One transaction: everything is applied or nothing is. Safe to run again: an already-upgraded group is skipped.
-- The statements inside each group are generated by ISTDocAi.OperatorTool (models upgrade-classifier /
-- upgrade-extract --generate-sql); only the per-machine snapshot check is replaced by an active-model check.
-- The Azure models live on the shared resource ist.cognitiveservices.azure.com; nothing is called from SQL.
SET NOCOUNT ON; SET XACT_ABORT ON;
BEGIN TRY
BEGIN TRANSACTION;
DECLARE @version int, @msg nvarchar(2048);
DECLARE @activeAuto varchar(64) = (SELECT ModelId FROM dbo.ModelRegistry WITH(UPDLOCK,HOLDLOCK)
    WHERE DocumentTypeCode='AUTO' AND Kind='classify' AND ShippingLineCode IS NULL AND Status='Active');
DECLARE @activeManifest varchar(64) = (SELECT ModelId FROM dbo.ModelRegistry WITH(UPDLOCK,HOLDLOCK)
    WHERE DocumentTypeCode='MANIFEST' AND Kind='extract' AND ShippingLineCode IS NULL AND Status='Active');
IF ISNULL(@activeAuto,'') NOT IN ('IST-Classifier-v6','IST-Classifier-v7')
BEGIN
    SET @msg = CONCAT(N'Active AUTO classifier is ', ISNULL(@activeAuto, N'(none)'), N'; expected IST-Classifier-v6. Nothing was changed.');
    THROW 50018, @msg, 1;
END;
IF ISNULL(@activeManifest,'') NOT IN ('manifest-v3','manifest-v4')
BEGIN
    SET @msg = CONCAT(N'Active MANIFEST model is ', ISNULL(@activeManifest, N'(none)'), N'; expected manifest-v3. Nothing was changed.');
    THROW 50018, @msg, 1;
END;

IF @activeAuto = 'IST-Classifier-v6'
BEGIN
IF EXISTS(SELECT 1 FROM dbo.ModelRegistry WITH(UPDLOCK,HOLDLOCK) WHERE ModelId='IST-Classifier-v7')
    THROW 50018,'New model ID already exists; use a new ID.',1;
SELECT @version=ISNULL(MAX(CONVERT(int,Version)),0)+1 FROM dbo.ModelRegistry WITH(UPDLOCK,HOLDLOCK) WHERE DocumentTypeCode='AUTO' AND Kind='classify' AND ShippingLineCode IS NULL;
INSERT dbo.ModelRegistry(ModelId,DocumentTypeCode,ShippingLineCode,Kind,Version,Status,TestFieldAccuracy,MinFieldConfidence)
VALUES('IST-Classifier-v7','AUTO',NULL,'classify',@version,'Testing',0.94,0.5);
INSERT dbo.ClassifierClasses(ClassifierModelId,ClassName,TargetDocumentTypeCode,ShippingLineCode) VALUES('IST-Classifier-v7','bill-of-lading','BL',NULL),('IST-Classifier-v7','cargo-manifest','MANIFEST',NULL),('IST-Classifier-v7','other',NULL,NULL);
EXEC sys.sp_executesql N'SET XACT_ABORT ON;
BEGIN TRANSACTION;

DECLARE @doc varchar(20), @line varchar(20), @kind varchar(10);
SELECT @doc = DocumentTypeCode, @line = ShippingLineCode, @kind = Kind
FROM dbo.ModelRegistry WITH (UPDLOCK, HOLDLOCK)
WHERE ModelId = @newModelId AND Status = ''Testing'' AND TestFieldAccuracy >= @minimumAccuracy;
IF @doc IS NULL THROW 50001, ''The new model is not in Testing or is below the accuracy gate.'', 1;
IF @kind = ''extract'' AND NOT EXISTS (
    SELECT 1 FROM dbo.ModelMappingBindings b WITH (UPDLOCK,HOLDLOCK)
    JOIN dbo.MappingProfiles p WITH (UPDLOCK,HOLDLOCK) ON p.ProfileId=b.ProfileId
    WHERE b.ModelId=@newModelId AND p.DocumentTypeCode=@doc)
    THROW 51205, ''Extract activation requires a matching mapping binding; register with -MappingFile.'', 1;
IF @kind = ''classify''
BEGIN
    -- HOLDLOCK protects the class map and target groups until activation commits.
    IF NOT EXISTS (SELECT 1 FROM dbo.ClassifierClasses WITH (UPDLOCK, HOLDLOCK)
                   WHERE ClassifierModelId = @newModelId AND TargetDocumentTypeCode IS NOT NULL)
        THROW 50003, ''A classifier needs at least one routable class before activation.'', 1;
    IF EXISTS (SELECT 1 FROM dbo.ClassifierClasses AS c WITH (UPDLOCK, HOLDLOCK)
               WHERE c.ClassifierModelId = @newModelId
                 AND ((c.TargetDocumentTypeCode IS NULL AND c.ShippingLineCode IS NOT NULL)
                   OR c.TargetDocumentTypeCode = ''AUTO''
                   OR (@doc <> ''AUTO'' AND (c.TargetDocumentTypeCode IS NULL OR c.TargetDocumentTypeCode <> @doc))
                   OR (c.TargetDocumentTypeCode IS NOT NULL AND NOT EXISTS
                       (SELECT 1 FROM dbo.ModelRegistry AS t WITH (UPDLOCK, HOLDLOCK)
                        WHERE t.DocumentTypeCode = c.TargetDocumentTypeCode AND t.Kind = ''extract''
                          AND (t.ShippingLineCode = c.ShippingLineCode OR (t.ShippingLineCode IS NULL AND c.ShippingLineCode IS NULL))))))
        THROW 50003, ''Classifier targets must identify supported extraction groups or intentional AUTO rejection.'', 1;
END;

UPDATE dbo.ModelRegistry WITH (HOLDLOCK)
SET Status = ''Retired'', RetiredAtUtc = SYSUTCDATETIME()
WHERE DocumentTypeCode = @doc AND Kind = @kind AND Status = ''Active''
  AND (ShippingLineCode = @line OR (ShippingLineCode IS NULL AND @line IS NULL));

UPDATE dbo.ModelRegistry SET Status = ''Active'', ActivatedAtUtc = SYSUTCDATETIME() WHERE ModelId = @newModelId;
COMMIT;

',N'@newModelId varchar(64),@minimumAccuracy decimal(5,4)',@newModelId='IST-Classifier-v7',@minimumAccuracy=0.6;
END;

IF @activeManifest = 'manifest-v3'
BEGIN
IF EXISTS(SELECT 1 FROM dbo.ModelRegistry WITH(UPDLOCK,HOLDLOCK) WHERE ModelId='manifest-v4')
    THROW 50018,'New model ID already exists; use a new ID.',1;
SELECT @version=ISNULL(MAX(CONVERT(int,Version)),0)+1 FROM dbo.ModelRegistry WITH(UPDLOCK,HOLDLOCK) WHERE DocumentTypeCode='MANIFEST' AND Kind='extract' AND ShippingLineCode IS NULL;
INSERT dbo.ModelRegistry(ModelId,DocumentTypeCode,ShippingLineCode,Kind,Version,Status,TestFieldAccuracy,MinFieldConfidence)
VALUES('manifest-v4','MANIFEST',NULL,'extract',@version,'Testing',0.877,0.8);
EXEC sys.sp_executesql N'-- Binding and profile locks live until the caller commits registration/activation.
DECLARE @mappingProfile bigint, @boundProfile bigint;
SELECT @boundProfile=ProfileId FROM dbo.ModelMappingBindings WITH(UPDLOCK,HOLDLOCK) WHERE ModelId=''manifest-v4'';
SELECT @mappingProfile=ProfileId FROM dbo.MappingProfiles WITH(UPDLOCK,HOLDLOCK) WHERE ProfileCode=''manifest-v4'';
IF @boundProfile IS NOT NULL SET @mappingProfile=@boundProfile;
DECLARE @mappingRows TABLE(MapKind varchar(12) COLLATE Latin1_General_100_BIN2, CanonicalKey varchar(64) COLLATE Latin1_General_100_BIN2, AzureName varchar(128) COLLATE Latin1_General_100_BIN2);
INSERT @mappingRows VALUES (''Bill'',''billOfLadingNumber'',''BLNumber''),(''Bill'',''bookingNumber'',''BookingNumber''),(''Bill'',''consigneeAddress'',''ConsigneeAddress''),(''Bill'',''consigneeName'',''ConsigneeName''),(''Bill'',''containerCount'',''ContainerCount''),(''Bill'',''description'',''Description''),(''Bill'',''freightTerms'',''FreightTerms''),(''Bill'',''grossWeight'',''GrossWeight''),(''Bill'',''hsCode'',''HSCode''),(''Bill'',''issueDate'',''IssueDate''),(''Bill'',''notifyParty'',''NotifyParty''),(''Bill'',''packageType'',''PackageType''),(''Bill'',''packages'',''Packages''),(''Bill'',''shipperAddress'',''ShipperAddress''),(''Bill'',''shipperName'',''ShipperName''),(''Container'',''billOfLadingNumber'',''BLNumber''),(''Container'',''containerNumber'',''ContainerNo''),(''Container'',''containerType'',''ContainerType''),(''Container'',''description'',''Description''),(''Container'',''grossWeight'',''GrossWeight''),(''Container'',''packages'',''Packages''),(''Container'',''sealNumber'',''SealNo''),(''Header'',''carrierName'',''CarrierName''),(''Header'',''manifestDate'',''ManifestDate''),(''Header'',''placeOfDelivery'',''PlaceOfDelivery''),(''Header'',''portOfDischarge'',''PortOfDischarge''),(''Header'',''portOfLoading'',''PortOfLoading''),(''Header'',''vesselName'',''VesselName''),(''Header'',''voyageNumber'',''VoyageNumber'');
IF @mappingProfile IS NULL
BEGIN
    INSERT dbo.MappingProfiles(ProfileCode,ProfileVersion,DocumentTypeCode,MappingShape,ContainersField,ContainerNumberField,SealNumberField,BillsOfLadingField,ChangeReference)
    VALUES(''manifest-v4'',1,''MANIFEST'',''ModelProfile'',''Containers'',''containerNumber'',''sealNumber'',''BillsOfLading'',CONVERT(nvarchar(256),0x6D0061006E00690066006500730074002D00760034003A0020004E00410044004900410020006C006100620065006C0020006600690078006500730020002800540045004D005500200072006F0077002C0020007300650061006C002F00460043004C0020007300680069006600740029002C00200032003000320036002D00310031002D0031003800));
    SET @mappingProfile=SCOPE_IDENTITY();
    INSERT dbo.MappingFields(ProfileId,MapKind,CanonicalKey,AzureName) SELECT @mappingProfile,MapKind,CanonicalKey,AzureName FROM @mappingRows;
END
ELSE IF NOT EXISTS (SELECT 1 FROM dbo.MappingProfiles WHERE ProfileId=@mappingProfile
    AND MappingShape=''ModelProfile'' AND ContainersField=''Containers''
    AND ContainerNumberField=''containerNumber'' AND SealNumberField=''sealNumber''
    AND BillsOfLadingField=''BillsOfLading''
    AND ChangeReference COLLATE Latin1_General_100_BIN2=CONVERT(nvarchar(256),0x6D0061006E00690066006500730074002D00760034003A0020004E00410044004900410020006C006100620065006C0020006600690078006500730020002800540045004D005500200072006F0077002C0020007300650061006C002F00460043004C0020007300680069006600740029002C00200032003000320036002D00310031002D0031003800) COLLATE Latin1_General_100_BIN2 AND DATALENGTH(ChangeReference)=DATALENGTH(CONVERT(nvarchar(256),0x6D0061006E00690066006500730074002D00760034003A0020004E00410044004900410020006C006100620065006C0020006600690078006500730020002800540045004D005500200072006F0077002C0020007300650061006C002F00460043004C0020007300680069006600740029002C00200032003000320036002D00310031002D0031003800)))
    OR EXISTS (SELECT MapKind,CanonicalKey,AzureName FROM @mappingRows EXCEPT SELECT MapKind,CanonicalKey,AzureName FROM dbo.MappingFields WHERE ProfileId=@mappingProfile)
    OR EXISTS (SELECT MapKind,CanonicalKey,AzureName FROM dbo.MappingFields WHERE ProfileId=@mappingProfile EXCEPT SELECT MapKind,CanonicalKey,AzureName FROM @mappingRows)
    THROW 51205, ''Conflicting mapping profile content; existing profiles are never overwritten.'', 1;
IF @mappingProfile IS NULL THROW 51205, ''no mapping profile for manifest-v4; supply -MappingFile'', 1;
IF NOT EXISTS (SELECT 1 FROM dbo.MappingProfiles WHERE ProfileId=@mappingProfile AND DocumentTypeCode=''MANIFEST'')
    THROW 51204, ''Mapping binding document type mismatch.'', 1;
IF @boundProfile IS NULL
    INSERT dbo.ModelMappingBindings(ModelId,ProfileId) VALUES(''manifest-v4'',@mappingProfile);';

EXEC sys.sp_executesql N'SET XACT_ABORT ON;
BEGIN TRANSACTION;

DECLARE @doc varchar(20), @line varchar(20), @kind varchar(10);
SELECT @doc = DocumentTypeCode, @line = ShippingLineCode, @kind = Kind
FROM dbo.ModelRegistry WITH (UPDLOCK, HOLDLOCK)
WHERE ModelId = @newModelId AND Status = ''Testing'' AND TestFieldAccuracy >= @minimumAccuracy;
IF @doc IS NULL THROW 50001, ''The new model is not in Testing or is below the accuracy gate.'', 1;
IF @kind = ''extract'' AND NOT EXISTS (
    SELECT 1 FROM dbo.ModelMappingBindings b WITH (UPDLOCK,HOLDLOCK)
    JOIN dbo.MappingProfiles p WITH (UPDLOCK,HOLDLOCK) ON p.ProfileId=b.ProfileId
    WHERE b.ModelId=@newModelId AND p.DocumentTypeCode=@doc)
    THROW 51205, ''Extract activation requires a matching mapping binding; register with -MappingFile.'', 1;
IF @kind = ''classify''
BEGIN
    -- HOLDLOCK protects the class map and target groups until activation commits.
    IF NOT EXISTS (SELECT 1 FROM dbo.ClassifierClasses WITH (UPDLOCK, HOLDLOCK)
                   WHERE ClassifierModelId = @newModelId AND TargetDocumentTypeCode IS NOT NULL)
        THROW 50003, ''A classifier needs at least one routable class before activation.'', 1;
    IF EXISTS (SELECT 1 FROM dbo.ClassifierClasses AS c WITH (UPDLOCK, HOLDLOCK)
               WHERE c.ClassifierModelId = @newModelId
                 AND ((c.TargetDocumentTypeCode IS NULL AND c.ShippingLineCode IS NOT NULL)
                   OR c.TargetDocumentTypeCode = ''AUTO''
                   OR (@doc <> ''AUTO'' AND (c.TargetDocumentTypeCode IS NULL OR c.TargetDocumentTypeCode <> @doc))
                   OR (c.TargetDocumentTypeCode IS NOT NULL AND NOT EXISTS
                       (SELECT 1 FROM dbo.ModelRegistry AS t WITH (UPDLOCK, HOLDLOCK)
                        WHERE t.DocumentTypeCode = c.TargetDocumentTypeCode AND t.Kind = ''extract''
                          AND (t.ShippingLineCode = c.ShippingLineCode OR (t.ShippingLineCode IS NULL AND c.ShippingLineCode IS NULL))))))
        THROW 50003, ''Classifier targets must identify supported extraction groups or intentional AUTO rejection.'', 1;
END;

UPDATE dbo.ModelRegistry WITH (HOLDLOCK)
SET Status = ''Retired'', RetiredAtUtc = SYSUTCDATETIME()
WHERE DocumentTypeCode = @doc AND Kind = @kind AND Status = ''Active''
  AND (ShippingLineCode = @line OR (ShippingLineCode IS NULL AND @line IS NULL));

UPDATE dbo.ModelRegistry SET Status = ''Active'', ActivatedAtUtc = SYSUTCDATETIME() WHERE ModelId = @newModelId;
COMMIT;

',N'@newModelId varchar(64),@minimumAccuracy decimal(5,4)',@newModelId='manifest-v4',@minimumAccuracy=0.6;
END;

SELECT DocumentTypeCode, ModelId, Kind, Version, MinFieldConfidence, TestFieldAccuracy, ActivatedAtUtc,
    CASE WHEN ModelId IN ('IST-Classifier-v7','manifest-v4','bl-v3') THEN 'OK' ELSE 'CHECK' END Result
FROM dbo.ModelRegistry WHERE Status='Active' AND ShippingLineCode IS NULL ORDER BY DocumentTypeCode;
COMMIT;
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK;
    THROW;
END CATCH;
